#!/usr/bin/env python3
"""Write java/com/tcc/iap2server/LeafiaCarPlayEvProfiles.java from profiles/*.json: the vehicle
profiles (from isaacwisdom/egmp-carplay-ev-routing) compiled in, picked by ro.build.product prefix.
Only cars whose framework the EV code has checked (LeafiaCarPlayEv.FRAMEWORKS)."""
import json, os
HERE = os.path.dirname(os.path.abspath(__file__))
CARS = [('NEEV23.', 'ioniq5'), ('NEEV.', 'ioniq5'), ('CVEV.', 'ev6')]
out = ['package com.tcc.iap2server;', '// SPDX-License-Identifier: GPL-3.0-or-later',
       '// generated by ev/carplay/gen-profiles.py from ev/carplay/profiles/*.json: do not edit', '',
       'final class LeafiaCarPlayEvProfiles {', '    private LeafiaCarPlayEvProfiles() {}']
names = sorted({n for _, n in CARS})
for n in names:
    s = json.dumps(json.load(open(os.path.join(HERE, 'profiles', n + '.json'))), separators=(',', ':'), sort_keys=True)
    out.append('    static final String %s = %s;' % (n.upper(), json.dumps(s)))
out.append('    /** {name, profile JSON} for a product id, or null */')
out.append('    static String[] forProduct(String product) {')
out.append('        if (product == null) return null;')
for prefix, n in CARS:
    out.append('        if (product.startsWith("%s")) return new String[] {"%s", %s};' % (prefix, n, n.upper()))
out.append('        return null;')
out += ['    }', '}', '']
open(os.path.join(HERE, 'java/com/tcc/iap2server/LeafiaCarPlayEvProfiles.java'), 'w').write('\n'.join(out))
print('LeafiaCarPlayEvProfiles.java: ' + ', '.join('%s=%s' % c for c in CARS))
